from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # current_grid is a list of lists of integers
        current_grid = message.message[0].data[0]
        # current_hint is a string
        current_hint = message.message[0].data[1]
        # player_idx is an integer: 1 or 2
        player_idx = message.message[0].data[2]

        # return a tuple (row_index, column_index), both are integers
        position_selected = None
        best_value = -1

        rows = len(current_grid)
        cols = len(current_grid[0]) if rows > 0 else 0

        def satisfies_hint(row, col, hint):
            operation, condition = hint.split(' ', 1)
            value = None
            if operation == 'sum':
                value = row + col
            elif operation == 'product':
                value = row * col
            elif operation == 'difference':
                value = abs(row - col)
            if value is None:
                return False
            if 'is less than' in condition:
                v1 = int(condition.split()[-1])
                return value < v1
            elif 'is greater than' in condition:
                v1 = int(condition.split()[-1])
                return value > v1
            elif 'contains digit' in condition:
                v1 = condition.split()[-1]
                return str(v1) in str(value)
            elif 'is even' in condition:
                return value % 2 == 0
            elif 'is odd' in condition:
                return value % 2 != 0
            elif 'is between' in condition:
                v1, v2 = map(int, condition.split()[2:])
                return v1 <= value <= v2
            return False

        def evaluate_position(row, col, player):
            if player == 1:
                # Player 1 wants to connect left and right sides
                left_connections = sum(current_grid[row][c] == 1 for c in range(col))
                right_connections = sum(current_grid[row][c] == 1 for c in range(col + 1, cols))
                return left_connections + right_connections
            elif player == 2:
                # Player 2 wants to connect top and bottom sides
                top_connections = sum(current_grid[r][col] == 2 for r in range(row))
                bottom_connections = sum(current_grid[r][col] == 2 for r in range(row + 1, rows))
                return top_connections + bottom_connections
            return 0

        for row in range(rows):
            for col in range(cols):
                if current_grid[row][col] == 0 and satisfies_hint(row + 1, col + 1, current_hint):
                    value = evaluate_position(row, col, player_idx)
                    if value > best_value:
                        best_value = value
                        position_selected = (row + 1, col + 1)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

