            elif 'is even' in condition:
                return value % 2 == 0
            elif 'is odd' in condition:
                return value % 2 != 0
            elif 'is between' in condition:
                v1, v2 = map(int, condition.split()[2:])
                return v1 <= value <= v2
            return False

        best_position = None
        best_score = -1

        for row in range(rows):
            for col in range(cols):
                if current_grid[row][col] == 0 and satisfies_hint(row + 1, col + 1, current_hint):
                    score = 0
