                        score += 1 - col / (cols - 1)  # Closer to left edge
                    else:
                        score += row / (rows - 1)  # Closer to bottom edge
                        score += 1 - row / (rows - 1)  # Closer to top edge
                    if score > best_score:
                        best_score = score
                        best_position = (row + 1, col + 1)

        position_selected = best_position

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
